	age       u32
	email     ?string
	tags      []string
	address   Address
	signed_up time.Time
	internal  string @[skip]
}

fn main() {
	user := User{
		name:      'Alice'
		age:       30
		email:     'alice@example.com'
		tags:      ['admin', 'beta']
		address:   Address{
			street: '1 Test Lane'
			city:   'Paris'
			zip:    '75000'
		}
		signed_up: time.parse_iso8601('2025-01-15T10:00:00Z') or { time.now() }
		internal:  'will not be encoded'
	}

	// 1. Generic typed encode/decode
	bytes := cbor.encode[User](user, cbor.EncodeOpts{})!
	println('encoded ${bytes.len} bytes: ${hex.encode(bytes)}')

	back := cbor.decode[User](bytes, cbor.DecodeOpts{})!
	println('round-trip name=${back.name} age=${back.age} city=${back.address.city}')

	// 2. Canonical encoding for stable hashing/signing
	mut m := map[string]int{}
	m['z'] = 26
	m['a'] = 1
	m['m'] = 13
	canonical := cbor.encode[map[string]int](m, cbor.EncodeOpts{
		canonical: true
	})!
	println('canonical map: ${hex.encode(canonical)}')

	// 3. Decode an unknown payload into a Value tree
	v := cbor.decode[cbor.Value](bytes, cbor.DecodeOpts{})!
	if name_val := v.get('name') {
		if s := name_val.as_string() {
			println('peeked name from Value tree: ${s}')
		}
	}

	// 4. Manual streaming: build a CBOR array of mixed types
	mut p := cbor.new_packer(cbor.EncodeOpts{})
	p.pack_array_header(3)
	p.pack_uint(42)
	p.pack_text('hello')
	p.pack_bool(true)
	stream_bytes := p.bytes()
	println('manual stream: ${hex.encode(stream_bytes)}')

	mut up := cbor.new_unpacker(stream_bytes, cbor.DecodeOpts{})
	n := up.unpack_array_header()!
	first := up.unpack_uint()!
	second := up.unpack_text()!
	third := up.unpack_bool()!
	println('unpacked array of ${n}: ${first}, "${second}", ${third}')
}

module main

import cli { Command, Flag }
import os

fn main() {
	mut cmd := Command{
		name:        'cli'
		description: 'An example of the cli library.'
		version:     '1.0.0'
	}
	mut greet_cmd := Command{
		name:          'greet'
		description:   'Prints greeting in different languages.'
		usage:         '<name>'
		required_args: 1
		pre_execute:   greet_pre_func
		execute:       greet_func
		post_execute:  greet_post_func
	}
	greet_cmd.add_flag(Flag{
		flag:        .string
		required:    true
		name:        'language'
		abbrev:      'l'
		description: 'Language of the message.'
	})
	greet_cmd.add_flag(Flag{
		flag:          .int
		name:          'times'
		default_value: ['3']
		description:   'Number of times the message gets printed.'
	})
	greet_cmd.add_flag(Flag{
		flag:        .string_array
		name:        'fun'
		description: 'Just a dumby flags to show multiple.'
	})
	cmd.add_command(greet_cmd)
	cmd.setup()
	cmd.parse(os.args)
}

fn greet_func(cmd Command) ! {
	language := cmd.flags.get_string('language') or {
		panic('Failed to get `language` flag: ${err}')
	}
	times := cmd.flags.get_int('times') or { panic('Failed to get `times` flag: ${err}') }
	name := cmd.args[0]
	for _ in 0 .. times {
		match language {
			'english', 'en' {
				println('Welcome ${name}')
			}
			'german', 'de' {
				println('Willkommen ${name}')
			}
			'dutch', 'nl' {
				println('Welkom ${name}')
			}
			else {
				println('Unsupported language')
				println('Supported languages are `english`, `german` and `dutch`.')
				break
			}
		}
	}
	fun := cmd.flags.get_strings('fun') or { panic('Failed to get `fun` flag: ${err}') }
	for f in fun {
		println('fun: ${f}')
	}
}

fn greet_pre_func(_cmd Command) ! {
	println('This is a function running before the main function.\n')
}

fn greet_post_func(_cmd Command) ! {
	println('\nThis is a function running after the main function.')
}

// This example demonstrates the `vlib/cli` features that show up automatically
// in `--help` when you populate the optional `group`, `examples` and
// `learn_more` fields of `Command`. No opt-in is required — leaving any of
// them empty simply skips the corresponding section.
//
// Compile from the V repo root:
//   v -o tasky examples/cli_groups.v
//
// Try it out:
//   ./tasky --help          # root help with grouped commands and examples
//   ./tasky issue --help    # sub-command help with INHERITED FLAGS
//   ./tasky issue list -v
//   ./tasky version
module main

import cli
import os

fn main() {
	mut app := cli.Command{
		name:        'tasky'
		description: 'A tiny issue tracker CLI'
		version:     '0.1.0'
		posix_mode:  true
		examples:    [
			'\$ tasky issue list',
			'\$ tasky issue create --title "Fix CI"',
			'\$ tasky config get editor',
		]
		learn_more:  'Use `tasky <command> --help` for details about a command.\nDocumentation lives at https://example.test/tasky'
	}
	app.add_flag(cli.Flag{
		flag:        .string
		name:        'config'
		abbrev:      'c'
		description: 'Path to a tasky config file'
		global:      true
	})
	app.add_command(issue_command())
	app.add_command(config_command())
	app.setup()
	app.parse(os.args)
}

fn issue_command() cli.Command {
	return cli.Command{
		name:        'issue'
		description: 'Work with issues'
		group:       'Core commands'
		commands:    [
			cli.Command{
				name:        'list'
				description: 'List open issues'
				execute:     issue_list
				flags:       [
					cli.Flag{
						flag:        .bool
						name:        'verbose'
