			cli.Command{
				name:        'create'
				description: 'Create a new issue'
				execute:     issue_create
				flags:       [
					cli.Flag{
						flag:        .string
						name:        'title'
						abbrev:      't'
						description: 'Title of the issue to create'
						required:    true
					},
				]
			},
		]
	}
}

fn config_command() cli.Command {
	return cli.Command{
		name:        'config'
		description: 'Read or write tasky settings'
		group:       'Additional commands'
		commands:    [
			cli.Command{
