import gg

pub struct Particle {
pub mut:
	color    gg.Color
	pos      Vector
	vel      Vector
	accel    Vector
	lifespan f32 = 255
}

pub fn (particle Particle) draw(mut ctx gg.Context) {
	ctx.draw_circle_filled(particle.pos.x, get_params().height - particle.pos.y,
		get_params().particle_radius, particle.color)
}

pub fn (mut particle Particle) tick(mut rocket Rocket, mut ctx gg.Context) {
	particle.lifespan -= get_params().age_rate
	particle.color.a = u8(particle.lifespan)

	if particle.lifespan <= 0 {
		rocket.dead = true
		return
	}

	particle.accel += get_params().gravity
	particle.vel += particle.accel
	particle.vel = particle.vel.mult(get_params().drag)
	particle.pos += particle.vel
	particle.draw(mut ctx)

	particle.accel = Vector{}
}

module objects

import gg
import rand

pub struct Rocket {
pub mut:
	color     gg.Color
	pos       Vector
	vel       Vector
	accel     Vector
	exploded  bool
	particles []Particle
	dead      bool
}

pub fn (rocket Rocket) draw(mut ctx gg.Context) {
	ctx.draw_circle_filled(rocket.pos.x, get_params().height - rocket.pos.y,
		get_params().rocket_radius, rocket.color)
}

pub fn (mut rocket Rocket) explode() {
	rocket.exploded = true

	for _ in 0 .. get_params().offspring_count {
		rocket.spawn_particle()
	}
}

pub fn (mut rocket Rocket) tick(mut ctx gg.Context) {
	if !rocket.exploded {
		if rocket.vel.y <= 1 {
			rocket.explode()
		}

		rocket.accel += get_params().gravity
		rocket.vel += rocket.accel
		rocket.pos += rocket.vel
		rocket.draw(mut ctx)

		rocket.accel = Vector{}
	}

	for mut particle in rocket.particles {
		particle.tick(mut rocket, mut ctx)
	}
}

pub fn new_rocket() Rocket {
	return Rocket{
		color: random_color()
		pos:   Vector{
			x: rand.f32_in_range(50, get_params().width - 50) or { 50 }
		}
		vel:   Vector{
			x: rand.f32_in_range(-1.5, 1.5) or { -1.5 }
			y: rand.f32_in_range(5, 7) or { 5 }
		}
	}
}

pub fn (mut rocket Rocket) spawn_particle() {
	rocket.particles << Particle{
		color: rocket.color
		pos:   rocket.pos
		accel: random_vector_in_circle().mult(2)
	}
}

module objects

import math
import rand

pub struct Vector {
pub mut:
	x f32
	y f32
}

pub fn (a Vector) + (b Vector) Vector {
	return Vector{a.x + b.x, a.y + b.y}
}

pub fn (vector Vector) mult(scalar f32) Vector {
	return Vector{vector.x * scalar, vector.y * scalar}
}

pub fn random_vector_in_circle() Vector {
	theta := rand.f32n(2 * math.pi) or { 0 }
	y := rand.f32()

	return Vector{
		x: f32(y * math.sin(theta))
		y: f32(y * math.cos(theta))
	}
}

