		draw_rect_filled(mut window, f32(separator_x), f32(frame + 6), 1,
			f32(titlebar - frame - 12), gg.rgb(28, 34, 43))
		draw_rect_filled(mut window, f32(separator_x + 1), f32(frame + 6), 1, f32(titlebar - frame -
