import gg
import os.asset
import sokol.sgl

// If you have emscripten (see https://emscripten.org/docs/getting_started/index.html), you can compile this program to WASM, using:
// `v -os wasm32_emscripten -o examples/gg/rotating_textured_quad.html examples/gg/rotating_textured_quad.v`, and later check with:
// `emrun examples/gg/rotating_textured_quad.html` .
#flag wasm32_emscripten --embed-file @VEXEROOT/examples/assets/logo.png@/assets/logo.png
#flag wasm32_emscripten --embed-file @VEXEROOT/examples/assets/fonts/RobotoMono-Regular.ttf@/assets/RobotoMono-Regular.ttf

@[heap]
pub struct Window {
pub mut:
	ctx &gg.Context = unsafe { nil }
	img gg.Image
}

pub fn (mut window Window) init() {
	image_path := asset.get_path('../assets', 'logo.png')
	window.img = window.ctx.create_image(image_path) or { panic(err) }
}

pub fn (mut window Window) draw() {
	angle := f32(window.ctx.frame) / 64 // since window.ctx.frame is increased by 1 on every frame -> the angle will be increasing too
	window.ctx.begin()
	sgl.load_pipeline(window.ctx.pipeline.alpha)

	sgl.translate(250, 250, 0) // center of the screen
	sgl.rotate(angle, 0.0, 0.0, 1.0) // rotate around the Z axis pointing towards the camera

	sgl.enable_texture()
	sgl.texture(window.img.simg, window.img.ssmp)
	sgl.begin_quads()
	sgl.c4b(255, 255, 255, 255)
	sgl.v3f_t2f(200, 200, 0, 1.0, 1.0)
	sgl.v3f_t2f(200, -200, 0, 1.0, 0.0)
	sgl.v3f_t2f(-200, -200, 0, 0.0, 0.0)
	sgl.v3f_t2f(-200, 200, 0, 0.0, 1.0)
	sgl.end()
	sgl.disable_texture()
	window.ctx.end()
}

fn main() {
	mut window := &Window{}
	window.ctx = gg.new_context(
		window_title: 'Rotating V logo'
		bg_color:     gg.light_green
		width:        500
		height:       500
		user_data:    window
		init_fn:      window.init
		frame_fn:     window.draw
		font_path:    asset.get_path('../assets', 'RobotoMono-Regular.ttf')
	)
	window.ctx.run()
}

import gg
import math

const pixel_count = 15000
const p = 3
const s = math.pi * 2 / f32(pixel_count)
const color = gg.Color{255, 255, 255, 255}
const background = gg.Color{20, 20, 64, 5}
const colors = [
	gg.Color{255, 255, 255, 255},
	gg.Color{255, 0, 255, 255},
	gg.Color{255, 255, 0, 255},
	gg.Color{0, 255, 255, 255},
	gg.Color{0, 0, 255, 255},
	gg.Color{0, 0, 0, 255},
]!

mut k := 497
mut scale := 200
gg.start(
	window_title: 'Spirograph'
	bg_color:     background
	width:        900
	height:       950
	sample_count: 2
	frame_fn:     fn [mut k, mut scale] (mut ctx gg.Context) {
		wsize := gg.window_size()
		ctx.begin()
		ctx.draw_rect_filled(0, 0, wsize.width, wsize.height, gg.Color{10, 1, 30, 60})
		t := f64(ctx.frame) / 300
		d := math.sin(t)
		if math.abs(d) < 0.0015 {
			k++
		}
		if ctx.pressed_keys[int(gg.KeyCode._0)] {
			ctx.frame = 475
		}
		if ctx.pressed_keys[int(gg.KeyCode.left)] {
			k--
		}
		if ctx.pressed_keys[int(gg.KeyCode.right)] {
			k++
		}
		if ctx.pressed_keys[int(gg.KeyCode.up)] {
			scale++
		}
		if ctx.pressed_keys[int(gg.KeyCode.down)] {
			scale--
		}
		d600 := math.sin(f64(ctx.frame) / 60)
		cd600 := math.cos(d600)
		mut pdj, mut pkj := [p]f64{}, [p]f64{}
		for j := 0; j < p; j++ {
			pdj[j], pkj[j] = math.pow(d, j), math.pow(k, j)
		}
		for i := 0; i < pixel_count; i++ {
			mut x, mut y := 0.0, 0.0
			for j := 0; j < p; j++ {
				a := pkj[j] * i * s
				x += pdj[j] * math.sin(a - t) * cd600
				y += pdj[j] * math.cos(a - t) * cd600
			}
			ctx.draw_rect_filled(f32(wsize.width / 2 + scale * x),
				f32(wsize.height / 2 + scale * y), 1, 1, colors[i % colors.len])
		}
		ctx.draw_text(wsize.width / 2 - 170, wsize.height - 15,
			'frame: ${ctx.frame:06}, k: ${k:4}, scale: ${scale:4}, arrows to change',
			color: colors[1]
		)
		ctx.end(how: .passthru)
	}
)

module main

import os.asset
import gg
import rand
import sokol.sgl

const win_width = 800
const win_height = 600
const max_stars = 5000
const max_v_letters = 5

struct Star {
mut:
	x f32
	y f32
	z f32
	r f32
	g f32
	b f32
}

struct VLetter {
mut:
	x      f32
	y      f32
	z      f32
	w      f32
	h      f32
	angle  f32
	dz     f32
	dangle f32
}

struct App {
mut:
	gg        &gg.Context = unsafe { nil }
	image     gg.Image
	stars     []Star
	v_letters []VLetter
}

fn main() {
	mut app := &App{
		stars:     []Star{len: max_stars}
		v_letters: []VLetter{len: max_v_letters}
	}
	app.gg = gg.new_context(
		bg_color:      gg.black
		width:         win_width
		height:        win_height
		create_window: true
		window_title:  'Star Vield'
		frame_fn:      frame
		init_fn:       init_images
		user_data:     app
	)
	for i in 0 .. max_stars {
		app.stars[i].x = rand.f32_in_range(-200.0, 200.0) or { -200.0 }
		app.stars[i].y = rand.f32_in_range(-200.0, 200.0) or { -200.0 }
		app.stars[i].z = rand.f32_in_range(-200.0, -100.0) or { -200.0 }
		app.stars[i].r = rand.f32_in_range(0.1, 1.0) or { 0.1 }
		app.stars[i].g = rand.f32_in_range(0.1, 1.0) or { 0.1 }
		app.stars[i].b = rand.f32_in_range(0.1, 1.0) or { 0.1 }
	}
	for i in 0 .. max_v_letters {
		app.v_letters[i].x = rand.f32_in_range(-20.0, 20.0) or { -20.0 }
		app.v_letters[i].y = rand.f32_in_range(-20.0, 20.0) or { -20.0 }
		app.v_letters[i].z = rand.f32_in_range(-5.0, -1.0) or { -5.0 }
		app.v_letters[i].w = rand.f32_in_range(5, 20) or { 5 }
		app.v_letters[i].h = app.v_letters[i].w
		app.v_letters[i].angle = rand.f32_in_range(0, 6.283184) or { 0 }
		app.v_letters[i].dangle = rand.f32_in_range(-0.05, 0.05) or { -0.05 }
		app.v_letters[i].dz = rand.f32_in_range(-0.1, -0.01) or { -0.1 }
	}
	app.gg.run()
}

fn init_images(mut app App) {
	logo_path := asset.get_path('../assets', 'logo.png')
	app.image = app.gg.create_image(logo_path) or { panic(err) }
}

fn frame(mut app App) {
	app.gg.begin()
	app.draw()
	app.gg.end()
}

// fn C.glPointSize(size f32)
fn (mut app App) draw() {
	sgl.defaults()
	sgl.perspective(sgl.rad(90), 1.0, 1.0, 100.0)
	// C.glPointSize(3.0)
	sgl.begin_points()
	for i in 0 .. app.stars.len {
		s := app.stars[i]
		sgl.v3f_c3f(s.x, s.y, s.z, s.r, s.g, s.b)
		app.stars[i].z += 0.3
		if app.stars[i].z > -1.0 {
			app.stars[i].x = rand.f32_in_range(-200.0, 200.0) or { -200.0 }
			app.stars[i].y = rand.f32_in_range(-200.0, 200.0) or { -200.0 }
