@['/sqlite-memory/:count']
pub fn (mut app App) sqlite_memory(mut ctx Context, count string) veb.Result {
	count_int := count.int()
	mut insert_stopwatchs := []int{}
	mut select_stopwatchs := []int{}
	mut update_stopwatchs := []int{}

	mut sw := time.new_stopwatch()

	mut db := sqlite.connect(':memory:') or { panic(err) }

	sql db {
		create table Task
	} or { panic(err) }

	task_model := Task{
		title:  'a'
		status: 'done'
	}

	// inserts
	for i := 0; i < count_int; i++ {
		sw.start()
		sql db {
			insert task_model into Task
		} or { panic(err) }
		sw.stop()
		insert_stopwatchs << int(sw.end - sw.start)
	}

	// selects
	for i := 0; i < count_int; i++ {
		sw.start()
		result := sql db {
			select from Task
		} or { []Task{} }
		sw.stop()
		eprintln(result)
		select_stopwatchs << int(sw.end - sw.start)
	}

	// updates
	for i := 0; i < count_int; i++ {
		sw.start()
		sql db {
			update Task set title = 'b', status = 'finish' where id == i
		} or { panic(err) }
		sw.stop()
		update_stopwatchs << int(sw.end - sw.start)
	}

	sql db {
		drop table Task
	} or { panic(err) }

	response := Response{
		insert: insert_stopwatchs
		select: select_stopwatchs
		update: update_stopwatchs
	}
	return ctx.json(response)
}

