// This example shows how to communicate with a child process (`bash` in this case), by sending
// commands to its stdin pipe, and reading responses from its stdout and stderr pipes.
// Note, you can use `if p.is_pending(.stdout) {` and `if p.is_pending(.stderr) {`, to check if
// there is available data in the pipes, without having to block in your main loop, if the data
// is missing or just not available yet.
import os
import time

const tmp_folder = os.join_path(os.temp_dir(), 'process_folder')

const max_txt_files = 20

fn exec(cmd string) (string, int, string) {
	mut out := []string{}
	mut er := []string{}
	mut rc := 0

	mut p := os.new_process('/bin/bash')
	p.set_redirect_stdio()
	p.run()

	p.stdin_write('echo "START         " && sleep 0.1 && ${cmd};\n')
	p.stdin_write('ECODE=\$?;\n')
	p.stdin_write('sleep 0.1;\n')
	p.stdin_write('exit \$ECODE;\n')

	// Note, that you can also ensure that `bash` will exit, when the command finishes,
	// by closing its stdin pipe. In the above example, that is not needed however, since
	// the last `exit` command, will make it quit as well.
	// os.fd_close(p.stdio_fd[0])

	for p.is_alive() {
		if data := p.pipe_read(.stderr) {
			eprintln('p.pipe_read .stderr, len: ${data.len:4} | data: `${data#[0..10]}`...')
			er << data
		}
		if data := p.pipe_read(.stdout) {
			eprintln('p.pipe_read .stdout, len: ${data.len:4} | data: `${data#[0..10]}`...')
			out << data
		}
		// avoid a busy loop, by sleeping a bit between each iteration
		time.sleep(2 * time.millisecond)
	}

	// the process finished, slurp all the remaining data in the pipes:
	out << p.stdout_slurp()
	er << p.stderr_slurp()
	p.close()
	p.wait()

	if p.code > 0 {
		eprintln('----------------------------------------------------------')
		eprintln('COMMAND: ${cmd}')
		eprintln('STDOUT:\n${out}')
		eprintln('STDERR:\n${er}')
		eprintln('----------------------------------------------------------')
		rc = 1
	}

	return out.join(''), rc, er.join('')
}

fn main() {
	mut out := ''
	mut er := ''
	mut ecode := 0

	// prepare some files in a temporary folder
	defer {
		os.rmdir_all(tmp_folder) or {}
	}
	os.mkdir_all(tmp_folder) or {}
	for i in 0 .. max_txt_files {
		os.write_file(os.join_path(tmp_folder, '${i}.txt'), '${i}\n${i}\n')!
	}

	out, ecode, er =
		exec("find ${os.quoted_path(tmp_folder)} ; sleep 0.1; find ${os.quoted_path(tmp_folder)} ; echo '******'")
	assert out.ends_with('******\n')
	assert er == ''

	out, ecode, er = exec('echo to stdout')
	assert out.contains('to stdout')
	assert er == ''

	out, ecode, er = exec('echo to stderr 1>&2')
	assert out.starts_with('START')
	assert er.contains('to stderr')

	out, ecode, er = exec('ls /sssss')
	assert out.starts_with('START')
	assert er != ''
	assert ecode > 0 // THIS STILL GIVES AN ERROR !

	println('test ok stderr & stdout is indeed redirected, ecode: ${ecode}')
}

module main

import datatypes
import gg
import time
import math
import rand

const win_width = 1340
const win_height = 640
const timer_period = 40 * time.millisecond // defaulted at 25 fps

const font_small = gg.TextCfg{
	color: gg.black
	size:  20
}

struct App {
mut:
	gg         &gg.Context
	qt         datatypes.Quadtree
	players    []datatypes.AABB
	particles  []Particle
	retrieveds []datatypes.AABB
	nodes      []datatypes.Quadtree
	width      f64 = 1340
	height     f64 = 640
}

struct Particle {
mut:
	pmt   datatypes.AABB
	speed f64
	angle f64
}

fn (mut p Particle) update() {
	p.pmt.x += p.speed * math.cos(p.angle * math.pi / 180)
	p.pmt.y += p.speed * math.sin(p.angle * math.pi / 180)

	if p.pmt.x < 0 {
		p.pmt.x = 0
		p.speed = -p.speed
		p.angle = -p.angle
	}
	if p.pmt.x > 1340 {
		p.pmt.x = 1340
		p.speed = -p.speed
		p.angle = -p.angle
	}
	if p.pmt.y < 0 {
		p.pmt.y = 0
		p.speed = -p.speed
		p.angle = 180 - p.angle
	}
	if p.pmt.y > 640 {
		p.pmt.y = 640
		p.speed = -p.speed
		p.angle = 180 - p.angle
	}
}

fn (mut app App) start() {
	app.players << datatypes.AABB{1200 * rand.f64(), 500 * rand.f64(), 20, 20}
	app.insert_particles()
	for mut particle in app.particles {
		particle.speed = 10 * rand.f64()
		particle.angle = 200 * rand.f64()
	}
	app.nodes << app.qt.get_nodes()
}

fn (mut app App) update() {
	app.qt.clear()
	app.nodes = []
	for mut particle in app.particles {
		particle.update()
		app.qt.insert(particle.pmt)
	}
	app.find_particles()
	app.nodes << app.qt.get_nodes()
}

fn (mut app App) insert_particles() {
	mut grid := 10.0
	mut gridh := app.qt.perimeter.width / grid
	mut gridv := app.qt.perimeter.height / grid
	num_particles := 100
	for _ in 0 .. num_particles {
		mut x := rand_minmax(0, gridh) * grid
		mut y := rand_minmax(0, gridv) * grid
		mut random_particle := datatypes.AABB{
			x:      x
			y:      y
			width:  rand_minmax(1, 4) * grid
			height: rand_minmax(1, 4) * grid
		}
		app.particles << Particle{random_particle, 0.0, 0.0}
	}
}

fn (mut app App) find_particles() {
	app.retrieveds = []
	app.retrieveds << app.qt.retrieve(app.players[0])
}

fn main() {
	mut app := &App{
		gg: unsafe { nil }
	}
	app.gg = gg.new_context(
		bg_color:      gg.white
		width:         win_width
		height:        win_height
		create_window: true
		window_title:  'Quadtree Demo'
		frame_fn:      frame
		event_fn:      on_event
		user_data:     app
	)
	app.qt = app.qt.create(0, 0, 1340, 640, 8, 4, 0)
	app.start()
	spawn app.run()
	app.gg.run()
}

fn (mut app App) on_mouse_move(mouse_x f32, mouse_y f32) {
	for mut player in app.players {
		player.x = (mouse_x / gg.window_size_real_pixels().width) * 1340
		player.y = (mouse_y / gg.window_size_real_pixels().height) * 640
	}
}

fn on_event(mut e gg.Event, mut app App) {
	match e.typ {
		.mouse_move { app.on_mouse_move(e.mouse_x, e.mouse_y) }
		else {}
	}
}

fn (mut app App) run() {
	for {
		app.update()
		time.sleep(timer_period)
	}
}

fn frame(app &App) {
	app.gg.begin()
	app.draw()
	app.gg.end()
}

fn (app &App) display() {
	for player in app.players {
		app.gg.draw_rect_filled(f32(player.x), f32(player.y), f32(player.width),
			f32(player.height), gg.black)
	}
	for particle in app.particles {
		app.gg.draw_rect_empty(f32(particle.pmt.x), f32(particle.pmt.y), f32(particle.pmt.width),
			f32(particle.pmt.height), gg.blue)
	}
	for node in app.nodes {
		app.gg.draw_rect_empty(f32(node.perimeter.x), f32(node.perimeter.y),
			f32(node.perimeter.width), f32(node.perimeter.height), gg.red)
	}
	for retrieved in app.retrieveds {
		app.gg.draw_rect_filled(f32(retrieved.x + 1), f32(retrieved.y + 1),
			f32(retrieved.width - 2), f32(retrieved.height - 2), gg.green)
	}
	app.gg.draw_text(1200, 25, 'Nodes: ${app.nodes.len}', font_small)
	app.gg.draw_text(1200, 50, 'Particles: ${app.particles.len}', font_small)
}

fn (app &App) draw() {
	app.display()
}

fn rand_minmax(min f64, max f64) f64 {
	mut val := min + (rand.f64() * (max - min))
	return val
}

import rand

const gen_len = 1000 // how many random numbers to generate

const gen_max = 10000

fn main() {
	mut arr := []int{}
	for _ in 0 .. gen_len {
		arr << rand.intn(gen_max) or { 0 }
	}
	println('length of random array is ${arr.len}')
	println('before quick sort whether array is sorted: ${is_sorted[int](arr)}')
	quick_sort[int](mut arr, 0, arr.len - 1)
	println('after quick sort whether array is sorted: ${is_sorted[int](arr)}')
}

fn quick_sort[T](mut arr []T, l int, r int) {
	if l >= r {
		return
	}
	mut sep := l // what is sep: [...all_value<arr[sep]...sep...all_value>=arr[sep]...]
	for i in l + 1 .. r + 1 {
		if arr[i] < arr[l] {
			sep++
			arr[i], arr[sep] = arr[sep], arr[i]
		}
	}
	arr[l], arr[sep] = arr[sep], arr[l]
	quick_sort[T](mut arr, l, sep - 1)
	quick_sort[T](mut arr, sep + 1, r)
}

fn is_sorted[T](arr []T) bool {
	for i in 0 .. arr.len - 1 {
		if arr[i] > arr[i + 1] {
			return false
		}
	}
	return true
}

