// of V's goroutine runtime (translated from Go's GMP scheduler).
//
// Compile: v -enable-globals -cc gcc -gc none -prod run goroutine_benchmark.v
// For comparison, see goroutine_benchmark.go.
//
// Note: Under the v1 compiler, the goroutines module uses pthreads-based
// sync.Mutex which has limitations with ucontext-based context switching.
// The v2 compiler will use a native spinlock, enabling higher scale.
module main

import goroutines
import sync
import time

__global bench_sem = sync.Semaphore{}
__global bench_n = int(0)
__global bench_chan1 = &goroutines.Chan(unsafe { nil })
__global bench_chan2 = &goroutines.Chan(unsafe { nil })
__global bench_msgs_per = int(0)

// --- fan-out/fan-in ---

fn fan_worker(arg voidptr) {
	c := unsafe { &goroutines.Chan(arg) }
	mut val := 1
	goroutines.chan_send(c, voidptr(&val), true)
}

fn fan_collector(arg voidptr) {
	c := unsafe { &goroutines.Chan(arg) }
	mut recv_val := 0
	for _ in 0 .. bench_n {
		goroutines.chan_recv(c, voidptr(&recv_val), true)
	}
	bench_sem.post()
}

fn bench_fan_out_fan_in(n int) {
	bench_n = n
	c := goroutines.chan_make(int(sizeof(int)), 0)

	sw := time.new_stopwatch()

	goroutines.goroutine_create(voidptr(&fan_collector), voidptr(c), 0)
	for _ in 0 .. n {
		goroutines.goroutine_create(voidptr(&fan_worker), voidptr(c), 0)
	}

	bench_sem.wait()

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / n
	C.printf(c'fan-out/fan-in  %d goroutines: %lld us  (%lld ns/goroutine)\n', n, us, ns_per)
}

// --- ping-pong ---

fn ping_side(arg voidptr) {
	mut val := 0
	for _ in 0 .. bench_n {
		goroutines.chan_send(bench_chan1, voidptr(&val), true)
		goroutines.chan_recv(bench_chan2, voidptr(&val), true)
	}
	bench_sem.post()
}

fn pong_side(arg voidptr) {
	mut val := 0
	for _ in 0 .. bench_n {
		goroutines.chan_recv(bench_chan1, voidptr(&val), true)
		val++
		goroutines.chan_send(bench_chan2, voidptr(&val), true)
	}
}

fn bench_ping_pong(n int) {
	bench_n = n
	bench_chan1 = goroutines.chan_make(int(sizeof(int)), 1)
	bench_chan2 = goroutines.chan_make(int(sizeof(int)), 1)

	sw := time.new_stopwatch()

	goroutines.goroutine_create(voidptr(&pong_side), unsafe { nil }, 0)
	goroutines.goroutine_create(voidptr(&ping_side), unsafe { nil }, 0)

	bench_sem.wait()

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / n
	C.printf(c'ping-pong       %d round-trips: %lld us  (%lld ns/round-trip)\n', n, us, ns_per)
}

// --- contended channel ---

fn producer(arg voidptr) {
	c := unsafe { &goroutines.Chan(arg) }
	mut val := 0
	for _ in 0 .. bench_msgs_per {
		val++
		goroutines.chan_send(c, voidptr(&val), true)
	}
}

fn consumer_fn(arg voidptr) {
	c := unsafe { &goroutines.Chan(arg) }
	mut recv_val := 0
	for _ in 0 .. bench_n {
		goroutines.chan_recv(c, voidptr(&recv_val), true)
	}
	bench_sem.post()
}

fn bench_contended_channel(num_producers int, msgs_per_producer int) {
	total := num_producers * msgs_per_producer
	bench_n = total
	bench_msgs_per = msgs_per_producer
	c := goroutines.chan_make(int(sizeof(int)), 64)

	sw := time.new_stopwatch()

	goroutines.goroutine_create(voidptr(&consumer_fn), voidptr(c), 0)
	for _ in 0 .. num_producers {
		goroutines.goroutine_create(voidptr(&producer), voidptr(c), 0)
	}

	bench_sem.wait()

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / total
	C.printf(c'contended chan  %d producers x %d msgs: %lld us  (%lld ns/msg)\n', num_producers,
		msgs_per_producer, us, ns_per)
}

fn main() {
	C.printf(c'=== V Goroutine Benchmark ===\n\n')

	bench_fan_out_fan_in(10)
	bench_fan_out_fan_in(50)
	bench_fan_out_fan_in(100)
	bench_fan_out_fan_in(500)

	C.printf(c'\n')
	bench_ping_pong(1000)
	bench_ping_pong(10000)
	bench_ping_pong(100000)

	C.printf(c'\n')
	bench_contended_channel(4, 1000)
	bench_contended_channel(10, 1000)

	C.printf(c'\n')
	goroutines.shutdown()
}

// V spawn (OS threads) benchmark – for comparison with Go goroutines.
//
// Uses V's built-in `spawn` (OS threads) and `chan` (V1 channels).
// This measures V's current threading primitives vs Go's goroutines.
//
// Run: v -prod run spawn_benchmark.v
module main

import time

// ---------------------------------------------------------------------------
// Benchmark 1 – fan-out / fan-in
// ---------------------------------------------------------------------------

fn fan_worker(c chan int) {
	c <- 1
}

fn bench_fan_out_fan_in(n int) {
	c := chan int{cap: n}

	sw := time.new_stopwatch()

	for _ in 0 .. n {
		spawn fan_worker(c)
	}

	for _ in 0 .. n {
		_ = <-c
	}

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / n
	println('fan-out/fan-in  ${n} threads: ${us} us  (${ns_per} ns/thread)')
}

// ---------------------------------------------------------------------------
// Benchmark 2 – channel ping-pong
// ---------------------------------------------------------------------------

fn pinger(c1 chan int, c2 chan int, n int) {
	mut val := 0
	for _ in 0 .. n {
		val = <-c1
		val++
		c2 <- val
	}
}

fn bench_ping_pong(n int) {
	c1 := chan int{cap: 1}
	c2 := chan int{cap: 1}

	spawn pinger(c1, c2, n)

	sw := time.new_stopwatch()

	mut val := 0
	for _ in 0 .. n {
		c1 <- val
		val = <-c2
	}

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / n
	println('ping-pong       ${n} round-trips: ${us} us  (${ns_per} ns/round-trip)')
}

// ---------------------------------------------------------------------------
// Benchmark 3 – contended channel (many producers, one consumer)
// ---------------------------------------------------------------------------

fn producer(c chan int, count int) {
	mut val := 0
	for _ in 0 .. count {
		val++
		c <- val
	}
}

fn bench_contended_channel(num_producers int, msgs_per_producer int) {
	total := num_producers * msgs_per_producer
	c := chan int{cap: 64}

	sw := time.new_stopwatch()

	for _ in 0 .. num_producers {
		spawn producer(c, msgs_per_producer)
	}

	for _ in 0 .. total {
		_ = <-c
	}

	elapsed := sw.elapsed()
	us := elapsed.microseconds()
	ns_per := elapsed.nanoseconds() / total
	println('contended chan  ${num_producers} producers x ${msgs_per_producer} msgs: ${us} us  (${ns_per} ns/msg)')
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

fn main() {
	println('=== V spawn (OS threads) Benchmark ===')
	println('')

	bench_fan_out_fan_in(1000)
	bench_fan_out_fan_in(10000)
	// Skip 100k - too many OS threads

	println('')
	bench_ping_pong(10000)
	bench_ping_pong(100000)

	println('')
	bench_contended_channel(10, 1000)
	bench_contended_channel(100, 1000)

	println('')
}

## Description

`sokol` is a thin wrapper around [sokol](https://github.com/floooh/sokol),
which in turn is a library of "Simple STB-style cross-platform libraries
for C and C++, written in C.", that provide access to graphics/audio/input
processing.

Each `.h` file in the sokol source code is well-documented as can be seen here:

[sokol_audio.h](https://github.com/floooh/sokol/blob/master/sokol_audio.h)

## Windows graphics backend

On Windows, sokol uses OpenGL by default. Compile with `-d sokol_d3d11` to opt in
to the D3D11 backend:

```sh
v -d sokol_d3d11 examples/gg/minimal.v
```

This selects `SOKOL_D3D11` and links D3D11/DXGI without changing the default
Windows OpenGL path. Screenshot/readback uses the selected backend, but real
D3D11 pixel correctness should be validated on Windows.

## Example from `@VEXEROOT/examples/sokol/sounds/simple_sin_tones.v`

```v cgen
import time
import math
import sokol.audio

const sw = time.new_stopwatch()
const sw_start_ms = sw.elapsed().milliseconds()

@[inline]
fn sintone(periods int, frame int, num_frames int) f32 {
	return math.sinf(f32(periods) * (2 * math.pi) * f32(frame) / f32(num_frames))
}

fn my_audio_stream_callback(buffer &f32, num_frames i32, num_channels i32) {
	frame_count := int(num_frames)
	channel_count := int(num_channels)
	ms := sw.elapsed().milliseconds() - sw_start_ms
	unsafe {
		mut soundbuffer := buffer
		for frame := 0; frame < frame_count; frame++ {
			for ch := 0; ch < channel_count; ch++ {
				idx := frame * channel_count + ch
				if ms < 250 {
					soundbuffer[idx] = 0.5 * sintone(20, frame, frame_count)
				} else if ms < 300 {
					soundbuffer[idx] = 0.5 * sintone(25, frame, frame_count)
				} else if ms < 1500 {
					soundbuffer[idx] *= sintone(22, frame, frame_count)
				} else {
					soundbuffer[idx] = 0.5 * sintone(25, frame, frame_count)
				}
			}
		}
	}
}

fn main() {
	audio.setup(
		stream_cb: my_audio_stream_callback
	)
	time.sleep(2000 * time.millisecond)
	audio.shutdown()
}
```

## Troubleshooting sokol apps

A common problem, if you draw a lot of primitive elements in the same frame,
is that there is a chance that your program can exceed the maximum
allowed amount of vertices and commands, imposed by `sokol`.

The symptom is that your frame will be suddenly black, after it
becomes more complex.

Sokol's default for vertices is 131072.
Sokol's default for commands is 32768.

To solve that, you can try adding these lines at the top of your program:
`#flag -D_SGL_DEFAULT_MAX_VERTICES=4194304`
`#flag -D_SGL_DEFAULT_MAX_COMMANDS=65536`
You can see an example of that in:
https://github.com/vlang/v/blob/master/examples/gg/examples/gg/many_thousands_of_circles_overriding_max_vertices.v

Another approach to that problem, is to draw everything yourself in a streaming
texture, then upload that streaming texture as a single draw command to the GPU.
You can see an example of that done in:
https://github.com/vlang/v/blob/master/examples/gg/random.v
and in:
https://github.com/vlang/v/blob/master/examples/gg/random_stars.v

A third approach, is to only upload your changing inputs to the GPU, and do all
the calculations and drawing there in shaders.

The `sync.pool` module provides a convenient way to run identical tasks over
an array of items *in parallel*, without worrying about thread synchronization,
waitgroups, mutexes etc.., you just need to supply a callback function, that
will be called once per each item in your input array.

After all the work is done in parallel by the worker threads in the pool,
pool.work_on_items will return. You can then call pool.get_results[Result]()
to retrieve a list of all the results, that the worker callbacks returned
for each input item. Example:

```v
import sync.pool

pub struct SResult {
	s string
}

fn sprocess(mut pp pool.PoolProcessor, idx int, wid int) &SResult {
	item := pp.get_item[string](idx)
	println('idx: ${idx}, wid: ${wid}, item: ' + item)
	return &SResult{item.reverse()}
}

fn main() {
	mut pp := pool.new_pool_processor(callback: sprocess)
	pp.work_on_items(['1abc', '2abc', '3abc', '4abc', '5abc', '6abc', '7abc'])
	// optionally, you can iterate over the results too:
	for x in pp.get_results[SResult]() {
		println('result: ${x.s}')
	}
}
```

See https://github.com/vlang/v/blob/master/vlib/sync/pool/pool_test.v for a
more detailed usage example.

## Description

The `term` module is designed to provide the building blocks for building
very simple TUI apps. For more complex apps, you should really look at the
`term.ui` module, as it includes terminal events, is easier to use and
is much more performant for large draws.

## Usage

You can use the `term` module to either color the output on a terminal
or to decide on where to put the output in your terminal.

For example let's make a simple program which prints colored text in the middle of the terminal.

```v
import term
import os

fn main() {
	term.clear() // clears the content in the terminal
	width, height := term.get_terminal_size() // get the size of the terminal
	term.set_cursor_position(x: width / 2, y: height / 2) // now we point the cursor to the middle of  the terminal
	println(term.strikethrough(term.bright_green('hello world'))) // Print green text
	term.set_cursor_position(x: 0, y: height) // Sets the position of the cursor to the bottom of the terminal
	// Keep prompting until the user presses the q key
	for {
		if var := os.input_opt('press q to quit: ') {
			if var != 'q' {
				continue
			}
			break
		}
		println('')
		break
	}
	println('Goodbye.')
}
```

This simple program covers many of the principal aspects of the `term ` module.

## API

Here are some of the main functions of the `term` module. Note that the
coloring/styling functions like `ok_message`, `yellow`, `bold`, etc., do
*not* print anything by themselves — they return a new string with ANSI
escape codes embedded, which you can then pass to `println` (or similar)
to actually display the styled text on stdout.

```v
import term
import os

// returns the height and the width of the terminal
width, height := term.get_terminal_size()
println('terminal dimensions: width: ${width} height: ${height}')

mut output := ''

// returns the string as green text
output = 'ok_message() text ' + term.ok_message('is green')
println(output)

// returns the string as red text
output = 'fail_message() text ' + term.fail_message('is red')
println(output)

// returns the string as yellow text
output = 'warn_message() text ' + term.warn_message('is yellow')
println(output)

os.input('hit Enter to clear the console and continue')

// clears the entire terminal
term.clear()

// Set the color output of the text.
// The available colors are:
// black, white, blue, yellow,
// green, red, cyan, magenta,
// bright_black, bright_white, bright_blue, bright_yellow,
// bright_green, bright_red, bright_cyan, bright_magenta,
output = 'yellow() - ' + term.yellow('text')
println(output)

// transforms the given string into bold text
output = 'bold() - ' + term.bold('text')
println(output)

// puts a strikethrough into the given string
output = 'strikethrough() - ' + term.strikethrough('text')
println(output)

// underlines the given string
output = 'underline() - ' + term.underline('text')
println(output)

// colors the background of the output following the given color
// the available colors are: black, blue, yellow, green, cyan, gray
output = 'bg_green() - ' + term.bg_green('text')
println(output)

// sets the position of the cursor
term.set_cursor_position(x: 5, y: 10)
println('Cursor at (5,10)')

// flashes (blinks) the text
output = term.slow_blink('done')
println(output)
```

The `term` module also provides several lower-level cursor-control
helpers, which write directly to stdout:

```v
import term

// moves the cursor up
term.cursor_up(1)
// moves the cursor down
term.cursor_down(1)
// moves the cursor to the right
term.cursor_forward(2)
// moves the cursor to the left
term.cursor_back(2)
// hides the cursor
term.hide_cursor()
// shows the cursor
term.show_cursor()
```

Call `term.show_cursor_on_exit()` before hiding the cursor to restore it when `main`
returns or `exit()` is called. This helper preserves the application's signal handlers.
Signal termination does not run exit callbacks. Applications that need cursor cleanup
on interruption should arrange to return from `main` or call `exit()` from normal execution.

# veb - the V Web Server

A simple yet powerful web server with built-in routing, parameter handling, templating, and other
features.

## Features

- **Very fast** performance of C on the web.
- **Templates are precompiled** all errors are visible at compilation time, not at runtime.
- **Middleware** functionality similar to other big frameworks.
- **HTTPS support** directly from `veb` via `mbedtls`.
- **Method-aware route middleware** for protecting only selected HTTP verbs.
- **Static compression** with gzip/zstd, including manual pre-compression support.
- **Controllers** to split up your apps logic.
- **Graceful shutdown** support in the `new_veb` backend.
- **Easy to deploy** just one binary file that also includes all templates. No need to install any
  dependencies.

## Quick Start

Run your veb app with a live reload via `v -d veb_livereload watch run .`

Now modifying any file in your web app (whether it's a .v file with the backend logic
or a compiled .html template file) will result in an instant refresh of your app
in the browser. No need to quit the app, rebuild it, and refresh the page in the browser!

Note: this works by injecting a small `<script>` tag before the ending `</html>` tag of the page,
that will check periodically if the current page has to be reloaded. In other words, it works for
template pages that have that `</html>` tag, or for ones that were produced by `ctx.html()` and that
also have that closing tag, but not for ones produced by `ctx.text()` .

## Port already in use

When `lsof` finds a process listening on the requested TCP port, veb displays its PID and asks
whether to terminate it. Reply `y` to send the process `SIGTERM`; any other response leaves it
running.

## Deploying veb apps

All the code, including HTML templates, is in one binary file. That's all you need to deploy.
Use the `-prod` flag when building for production.

## Getting Started

To start, you must import the module `veb` and define a structure which will
represent your app and a structure which will represent the context of a request.
These structures must be declared with the `pub` keyword.

**Example:**

```v
module main

import veb

pub struct User {
pub mut:
	name string
	id   int
}

// Our context struct must embed `veb.Context`!
pub struct Context {
	veb.Context
pub mut:
	// In the context struct we store data that could be different
	// for each request. Like a User struct or a session id
	user       User
	session_id string
}

pub struct App {
pub:
	// In the app struct we store data that should be accessible by all endpoints.
	// For example, a database or configuration values.
	secret_key string
}

// This is how endpoints are defined in veb. This is the index route
pub fn (app &App) index(mut ctx Context) veb.Result {
	return ctx.html('<html><body><h1>Hello V!</h1><p>The secret key is "${app.secret_key}"</body></html>')
}

fn main() {
	mut app := &App{
		secret_key: 'secret'
	}
	// Pass the App and context type and start the web server on port 8080
	veb.run[App, Context](mut app, 8080)
}
```

You can use the `App` struct for data you want to keep during the lifetime of your program,
or for data that you want to share between different routes.

A new `Context` struct is created every time a request is received,
so it can contain different data for each request.

## Parallel picoev workers

The default non-SSL picoev backend can start more than one event loop by setting
`nr_workers` in `RunParams`:

```v
module main

import runtime
import veb

pub struct Context {
	veb.Context
}

pub struct App {}

pub fn (app &App) index(mut ctx Context) veb.Result {
	return ctx.text('Hello from parallel veb')
}

fn main() {
	mut app := &App{}
	veb.run_at[App, Context](mut app,
		host:       '0.0.0.0'
		port:       8080
		nr_workers: runtime.nr_jobs()
	) or { panic(err) }
}
```

`nr_workers` defaults to `1` to preserve the historical single-loop behavior.
It controls the default non-SSL picoev backend (currently on Linux or Termux).
With `-d use_openssl`, it also limits concurrent TLS handshakes, so the default
serializes handshakes. When running with `-d new_veb`, the fasthttp backend is
already multi-threaded and ignores `nr_workers`.

## Request-scoped allocation with `-prealloc`

When a `veb` app runs on the `fasthttp` backend and is compiled with
`-prealloc`, each request is handled inside a scoped prealloc arena created by
`fasthttp`. V allocations made while decoding the request, creating the
`veb.Context`, matching routes, running middleware, rendering templates, and
serializing the response all use that request arena.

The arena is freed after the response has been sent, not merely when the route
handler returns. On macOS and BSD, the response buffer can be retained by the
connection while `kqueue` finishes writing it; the arena is detached from the
request thread and freed after the write completes. This keeps request-local
allocations cheap while preserving response-buffer lifetime.

When a handler starts V `spawn` work while the request scope is active, the
generated thread wrapper retains the request arena until the spawned function
returns, so veb app code does not need to manually copy request strings just to
pass them to a background task. Void spawned functions also run inside their own
scoped arena, which is freed at thread exit. Do not store request-scoped strings,
arrays, maps, `Context` values, or template output in app fields, globals, or
caches unless you deliberately copy them into longer-lived storage. Process
startup data, route tables, static file maps, database pools, and allocations
made directly by C libraries are not part of the per-request arena.

To trace request arena allocation and free points while developing, build with:

```sh
v -prealloc -d trace_prealloc -d new_veb run .
```

## HTTPS

To serve HTTPS directly from `veb`, pass an SSL configuration in `RunParams`.
The default backend expects `mbedtls.SSLConnectConfig`. When compiling with
`-d use_openssl`, use `openssl.SSLConnectConfig` instead. For example, run the
following OpenSSL-backed server with `v -d use_openssl run .`:

```v oksyntax
module main

import net.openssl
import veb

pub struct Context {
	veb.Context
}

pub struct App {}

pub fn (app &App) index(mut ctx Context) veb.Result {
	return ctx.text('Hello over HTTPS')
}

fn main() {
	mut app := &App{}
	veb.run_at[App, Context](mut app,
		host:       '0.0.0.0'
		port:       8443
		family:     .ip
		ssl_config: openssl.SSLConnectConfig{
			cert:     'certs/server.crt'
			cert_key: 'certs/server.key'
		}
	) or { panic(err) }
}
```

## Graceful shutdown

When running with `-d new_veb`, the underlying server supports graceful
shutdown. Once shutdown begins, it stops accepting new requests, waits for
in-flight requests to finish, and only then exits. This is useful for deploys,
tests, and management endpoints that trigger a stop after sending a response.

You can store the server handle in your app by adding an optional
`init_server(server &veb.Server)` method:

```v
module main

import veb

pub struct App {
pub mut:
	server &veb.Server = unsafe { nil }
}

pub fn (mut app App) init_server(server &veb.Server) {
	app.server = server
}
```

`veb.Server` forwards `wait_till_running()` and `shutdown(timeout: ...)`
to the `new_veb` backend. These lifecycle controls are available only when
running with `-d new_veb` without SSL.

## Defining endpoints

To add endpoints to your web server, you must extend the `App` struct.
For routing you can either use auto-mapping of function names or specify the path as an attribute.
The function expects a parameter of your Context type and a response of the type `veb.Result`.

**Example:**

```v ignore
// This endpoint can be accessed via http://server:port/hello
pub fn (app &App) hello(mut ctx Context) veb.Result {
	return ctx.text('Hello')
}

// This endpoint can be accessed via http://server:port/foo
@['/foo']
pub fn (app &App) world(mut ctx Context) veb.Result {
	return ctx.text('World')
}
```

### HTTP verbs

To use any HTTP verbs (or methods, as they are properly called),
such as `@[post]`, `@[get]`, `@[put]`, `@[patch]` or `@[delete]`
you can simply add the attribute before the function definition.

**Example:**

```v ignore
// only GET requests to http://server:port/world are handled by this method
@[get]
pub fn (app &App) world(mut ctx Context) veb.Result {
	return ctx.text('World')
}

// only POST requests to http://server:port/product/create are handled by this method
@['/product/create'; post]
pub fn (app &App) create_product(mut ctx Context) veb.Result {
	return ctx.text('product')
}
```

By default, endpoints are marked as GET requests only. It is also possible to
add multiple HTTP verbs per endpoint.

**Example:**

```v ignore
// only GET and POST requests to http://server:port/login are handled by this method
@['/login'; get; post]
pub fn (app &App) login(mut ctx Context) veb.Result {
	if ctx.req.method == .get {
		// show the login page on a GET request
		return ctx.html('<h1>Login page</h1><p>todo: make form</p>')
	} else {
		// request method is POST
		password := ctx.form['password']
		// validate password length
		if password.len < 12 {
			return ctx.text('password is too weak!')
		} else {
			// we receive a POST request, so we want to explicitly tell the browser
			// to send a GET request to the profile page.
			return ctx.redirect('/profile')
		}
	}
}
```

### Routes with Parameters

Parameters are passed directly to an endpoint route using the colon sign `:`. The route
parameters are passed as arguments. V will cast the parameter to any of V's primitive types
(`string`, `int` etc,).

To pass a parameter to an endpoint, you simply define it inside an attribute, e. g.
`@['/hello/:user]`.
After it is defined in the attribute, you have to add it as a function parameter.
Parameters after `ctx` are populated from strings, so they currently must be `string`,
integer, or `bool`.

**Example:**

```v ignore
// V will pass the parameter 'user' as a string
           vvvv
@['/hello/:user']                             vvvv
pub fn (app &App) hello_user(mut ctx Context, user string) veb.Result {
	return ctx.text('Hello ${user}')
}

// V will pass the parameter 'id' as an int
              vv
@['/document/:id']                              vv
pub fn (app &App) get_document(mut ctx Context, id int) veb.Result {
	return ctx.text('Document ${id}')
}
```

If we visit http://localhost:port/hello/vaesel we would see the text `Hello vaesel`.

### Routes with Parameter Arrays

If you want multiple parameters in your route and if you want to parse the parameters
yourself, or you want a wildcard route, you can add `...` after the `:` and name,
e.g. `@['/:path...']`.

This will match all routes after `'/'`. For example, the url `/path/to/test` would give
`path = '/path/to/test'`.

```v ignore
         vvv
@['/:path...']                              vvvv
pub fn (app &App) wildcard(mut ctx Context, path string) veb.Result {
	return ctx.text('URL path = "${path}"')
}
```

### Query, Form and Files

You have direct access to query values by accessing the `query` field on your context struct.
You are also able to access any formdata or files that were sent
with the request with the fields `.form` and `.files` respectively.

In the following example, visiting http://localhost:port/user?name=veb we
will see the text `Hello veb!`. And if we access the route without the `name` parameter,
http://localhost:port/user, we will see the text `no user was found`,

**Example:**

```v ignore
@['/user'; get]
pub fn (app &App) get_user_by_id(mut ctx Context) veb.Result {
	user_name := ctx.query['name'] or {
		// we can exit early and send a different response if no `name` parameter was passed
		return ctx.text('no user was found')
	}

	return ctx.text('Hello ${user_name}!')
}
```

### Host

# Direct access to .md file always works, regardless of Accept header
curl http://localhost:8080/api.md

# Direct access to .html file
curl http://localhost:8080/api.html

# Without Accept: text/markdown header - returns 404 since 'api' without extension doesn't exist
curl http://localhost:8080/api
```

## Middleware

Middleware in web development is (loosely defined) a hidden layer that sits between
what a user requests (the HTTP Request) and what a user sees (the HTTP Response).
We can use this middleware layer to provide "hidden" functionality to our apps endpoints.

To use veb's middleware we have to embed `veb.Middleware` on our app struct and provide
the type of which context struct should be used.

**Example:**

```v ignore
pub struct App {
	veb.Middleware[Context]
}
```

### Use case

We could, for example, get the cookies for an HTTP request and check if the user has already
accepted our cookie policy. Let's modify our Context struct to store whether the user has
accepted our policy or not.

**Example:**

```v ignore
pub struct Context {
	veb.Context
pub mut:
	has_accepted_cookies bool
}
```

In veb middleware functions take a `mut` parameter with the type of your context struct
and must return `bool`. We have full access to modify our Context struct!

Middleware handlers can also be bound methods, such as `app.session_middleware`.
That lets middleware read or update fields on your app struct and reuse resources that
live on it.

The return value indicates to veb whether it can continue or has to stop. If we send a
response to the client in a middleware function veb has to stop, so we return `false`.

**Example:**

```v ignore
pub fn check_cookie_policy(mut ctx Context) bool {
	// get the cookie
	cookie_value := ctx.get_cookie('accepted_cookies') or { '' }
	// check if the cookie has been set
	if cookie_value == 'true' {
		ctx.has_accepted_cookies = true
	}
	// we don't send a response, so we must return true
	return true
}
```

We can check this value in an endpoint and return a different response.

**Example:**

```v ignore
@['/only-cookies']
pub fn (app &App) only_cookie_route(mut ctx Context) veb.Result {
	if ctx.has_accepted_cookies {
		return ctx.text('Welcome!')
	} else {
		return ctx.text('You must accept the cookie policy!')
	}
}
```

There is one thing left for our middleware to work: we have to register our `only_cookie_route`
function as middleware for our app. We must do this after the app is created and before the
app is started.

**Example:**

```v ignore
fn main() {
	mut app := &App{}

	// register middleware for all routes
	app.use(handler: check_cookie_policy)

	// Pass the App and context type and start the web server on port 8080
	veb.run[App, Context](mut app, 8080)
}
```

If your middleware needs access to app state or shared resources, register a bound
method instead of a free function:

```v ignore
@[heap]
pub struct App {
	veb.Middleware[Context]
mut:
	request_count int
}

pub fn (mut app App) session_middleware(mut ctx Context) bool {
	app.request_count++
	ctx.res.header.add_custom('X-Request-Count', app.request_count.str()) or { return false }
	return true
}

fn main() {
	mut app := &App{}
	app.use(handler: app.session_middleware)
	app.route_use('/admin/:path...', handler: app.session_middleware)
	veb.run[App, Context](mut app, 8080)
}
```

### Types of middleware

In the previous example we used so called "global" middleware. This type of middleware
applies to every endpoint defined on our app struct; global. It is also possible
to register middleware for only a certain route(s).

**Example:**

```v ignore
// register middleware only for the route '/auth'
app.route_use('/auth', handler: auth_middleware)
// register middleware only for the route '/documents/' with a parameter
// e.g. '/documents/5'
app.route_use('/documents/:id')
// register middleware with a parameter array. The middleware will be registered
// for all routes that start with '/user/' e.g. '/user/profile/update'
app.route_use('/user/:path...')
// register middleware only for selected HTTP methods on a route
app.route_use('/admin/auth', handler: auth_middleware, methods: [.get, .delete])
```

If `methods` is omitted, route middleware applies to all HTTP methods on that route.

### Evaluation moment

By default, the registered middleware functions are executed *before* a method on your
app struct is called. You can also change this behaviour to execute middleware functions
*after* a method on your app struct is called, but before the response is sent!

**Example:**

```v ignore
pub fn modify_headers(mut ctx Context) bool {
	// add Content-Language: 'en-US' header to each response
	ctx.res.header.add(.content_language, 'en-US')
	return true
}
```

```v ignore
app.use(handler: modify_headers, after: true)
```

#### When to use which type

You could use "before" middleware to check and modify the HTTP request and you could use
"after" middleware to validate the HTTP response that will be sent or do some cleanup.

Anything you can do in "before" middleware, you can do in "after" middleware.

### Evaluation order

veb will handle requests in the following order:

1. Execute global "before" middleware
2. Execute "before" middleware that matches the requested route
3. Execute the endpoint handler on your app struct
4. Execute global "after" middleware
5. Execute "after" middleware that matches the requested route

In each step, except for step `3`, veb will evaluate the middleware in the order that
they are registered; when you call `app.use` or `app.route_use`.

### Early exit

If any middleware sends a response (and thus must return `false`) veb will not execute any
other middleware, or the endpoint method, and immediately send the response.

**Example:**

```v ignore
pub fn early_exit(mut ctx Context) bool {
	ctx.text('early exit')
	// we send a response from middleware, so we have to return false
	return false
}

pub fn logger(mut ctx Context) bool {
	println('received request for "${ctx.req.url}"')
	return true
}
```

```v ignore
app.use(handler: early_exit)
app.use(handler: logger)
```

Because we register `early_exit` before `logger` our logging middleware will never be executed!

## Controllers

Controllers can be used to split up your app logic so you are able to have one struct
per "route group". E.g. a struct `Admin` for urls starting with `'/admin'` and a struct `Foo`
for urls starting with `'/foo'`.

To use controllers we have to embed `veb.Controller` on
our app struct and when we register a controller we also have to specify
what the type of the context struct will be. That means that it is possible
to have a different context struct for each controller and the main app struct.

**Example:**

```v
module main

import veb

pub struct Context {
	veb.Context
}

pub struct App {
	veb.Controller
}

// this endpoint will be available at '/'
pub fn (app &App) index(mut ctx Context) veb.Result {
	return ctx.text('from app')
}

pub struct Admin {}

// this endpoint will be available at '/admin/'
pub fn (app &Admin) index(mut ctx Context) veb.Result {
	return ctx.text('from admin')
}

pub struct Foo {}

// this endpoint will be available at '/foo/'
pub fn (app &Foo) index(mut ctx Context) veb.Result {
	return ctx.text('from foo')
}

fn main() {
	mut app := &App{}

	// register the controllers the same way as how we start a veb app
	mut admin_app := &Admin{}
	app.register_controller[Admin, Context]('/admin', mut admin_app)!

	mut foo_app := &Foo{}
	app.register_controller[Foo, Context]('/foo', mut foo_app)!

	veb.run[App, Context](mut app, 8080)
}
```

You can do everything with a controller struct as with a regular `App` struct.
Register middleware, add static files and you can even register other controllers!
Static assets registered on either the main app or a controller keep working when
controllers are mounted, including controllers mounted at `'/'`.

### Routing

Any route inside a controller struct is treated as a relative route to its controller namespace.

```v ignore
@['/path']
pub fn (app &Admin) path(mut ctx Context) veb.Result {
    return ctx.text('Admin')
}
```

When we registered the controller with
`app.register_controller[Admin, Context]('/admin', mut admin_app)!`
we told veb that the namespace of that controller is `'/admin'` so in this example we would
see the text "Admin" if we navigate to the url `'/admin/path'`.

veb doesn't support duplicate routes, so if we add the following
route to the example the code will produce an error.

```v ignore
@['/admin/path']
pub fn (app &App) admin_path(mut ctx Context) veb.Result {
    return ctx.text('Admin overwrite')
}
```

There will be an error, because the controller `Admin` handles all routes starting with
`'/admin'`: the endpoint `admin_path` is unreachable.

### Controller with hostname

You can also set a host for a controller. All requests coming to that host will be handled
by the controller.

**Example:**

```v ignore
struct Example {}

// You can only access this route at example.com: http://example.com/
pub fn (app &Example) index(mut ctx Context) veb.Result {
	return ctx.text('Example')
}
```

```v ignore
mut example_app := &Example{}
// set the controllers hostname to 'example.com' and handle all routes starting with '/',
// we handle requests with any route to 'example.com'
app.register_host_controller[Example, Context]('example.com', '/', mut example_app)!
```

## Context Methods

veb has a number of utility methods that make it easier to handle requests and send responses.
These methods are available on `veb.Context` and directly on your own context struct if you
embed `veb.Context`. Below are some of the most used methods, look at the
[standard library documentation](https://modules.vlang.io/) to see them all.

### Request methods

You can directly access the HTTP request on the `.req` field.

#### Get request headers

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	content_length := ctx.get_header(.content_length) or { '0' }
	// get custom header
	custom_header := ctx.get_custom_header('X-HEADER') or { '' }
	// ...
}
```

#### Get a cookie

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	cookie_val := ctx.get_cookie('token') or { '' }
	// ...
}
```

### Response methods

You can directly modify the HTTP response by changing the `res` field,
which is of the type `http.Response`.

#### Send response with different MIME types

```v ignore
// send response HTTP_OK with content-type `text/html`
ctx.html('<h1>Hello world!</h1>')
// send response HTTP_OK with content-type `text/plain`
ctx.text('Hello world!')
// stringify the object and send response HTTP_OK with content-type `application/json`
ctx.json(User{
	name: 'test'
	age: 20
})
// send response HTTP_NO_CONTENT (204) without a content-type and body
ctx.no_content()
```

#### Sending files

**Example:**

```v ignore
pub fn (app &App) file_response(mut ctx Context) veb.Result {
	// send the file 'image.png' in folder 'data' to the user
	return ctx.file('data/image.png')
}
```

#### Set response headers

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	ctx.set_header(.accept, 'text/html')
	// set custom header
	ctx.set_custom_header('X-HEADER', 'my-value')!
	// ...
}
```

#### Set a cookie

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	ctx.set_cookie(http.Cookie{
		name: 'token'
		value: 'true'
		path: '/'
		secure: true
		http_only: true
	})
	// ...
}
```

#### Redirect

You must pass the type of redirect to veb:

- `moved_permanently` HTTP code 301
- `found` HTTP code 302
- `see_other` HTTP code 303
- `temporary_redirect` HTTP code 307
- `permanent_redirect` HTTP code 308

**Common use cases:**

If you want to change the request method, for example when you receive a post request and
want to redirect to another page via a GET request, you should use `see_other`. If you want
the HTTP method to stay the same, you should use `found` generally speaking.

**Example:**

```v ignore
pub fn (app &App) index(mut ctx Context) veb.Result {
	token := ctx.get_cookie('token') or { '' }
	if token == '' {
		// redirect the user to '/login' if the 'token' cookie is not set
		// we explicitly tell the browser to send a GET request
		return ctx.redirect('/login', typ: .see_other)
	} else {
		return ctx.text('Welcome!')
	}
}
```

#### Sending error responses

**Example:**

```v ignore
pub fn (app &App) login(mut ctx Context) veb.Result {
	if username := ctx.form['username'] {
		return ctx.text('Hello "${username}"')
	} else {
		// send an HTTP 400 Bad Request response with a message
		return ctx.request_error('missing form value "username"')
	}
}
```

You can also use `ctx.server_error(msg string)` to send an HTTP 500 internal server
error with a message.

## Advanced usage

If you need more control over the TCP connection with a client, for example when
you want to keep the connection open. You can call `ctx.takeover_conn`.

When this function is called you are free to do anything you want with the TCP
connection and veb will not interfere. This means that we are responsible for
sending a response over the connection and closing it.

### Empty Result

Sometimes you want to send the response in another thread, for example when using
[Server Sent Events](sse/README.md). When you are sure that a response will be sent
over the TCP connection you can return `veb.no_result()`. This function does nothing
and returns an empty `veb.Result` struct, letting veb know that we sent a response ourselves.

> **Note:**
> It is important to call `ctx.takeover_conn` before you spawn a thread

**Example:**

```v
module main

import net
import time
import veb

pub struct Context {
	veb.Context
}

pub struct App {}

pub fn (app &App) index(mut ctx Context) veb.Result {
	return ctx.text('hello!')
}

@['/long']
pub fn (app &App) long_response(mut ctx Context) veb.Result {
	// let veb know that the connection should not be closed
	ctx.takeover_conn()
	// use spawn to handle the connection in another thread
	// if we don't the whole web server will block for 10 seconds,
	// since veb is singlethreaded
	spawn handle_connection(mut ctx.conn)
	// we will send a custom response ourselves, so we can safely return an empty result
	return veb.no_result()
}

fn handle_connection(mut conn net.TcpConn) {
	defer {
		conn.close() or {}
	}
	// block for 10 second
	time.sleep(time.second * 10)
	conn.write_string('HTTP/1.1 200 OK\r\nContent-type: text/html\r\nContent-length: 15\r\n\r\nHello takeover!') or {}
}

fn main() {
	mut app := &App{}
	veb.run[App, Context](mut app, 8080)
}
```

## Description

`veb.auth` is a module that helps with common logic required for authentication.

It allows to easily generate hashed and salted passwords and to compare password hashes.

It also handles authentication tokens, including DB table creation and insertion.
All DBs are supported.

## Usage

```v
import veb
import db.pg
import veb.auth

pub struct App {
	veb.StaticHandler
pub mut:
	db   pg.DB
	auth auth.Auth[pg.DB] // or auth.Auth[sqlite.DB] etc
}

const port = 8081

pub struct Context {
	veb.Context
	current_user User
}

struct User {
	id            int @[primary; sql: serial]
	name          string
	password_hash string
	salt          string
}

fn main() {
	mut app := &App{
		// Use your actual local PostgreSQL password here.
		db: pg.connect(
			host:     'localhost'
			user:     'postgres'
			password: 'password'
			dbname:   'postgres'
		)!
	}
	app.auth = auth.new(app.db)
	veb.run[App, Context](mut app, port)
}

@[post]
pub fn (mut app App) register_user(mut ctx Context, name string, password string) veb.Result {
	salt := auth.generate_salt()
	new_user := User{
		name:          name
		password_hash: auth.hash_password_with_salt(password, salt)
		salt:          salt
	}
	user_id := sql app.db {
		insert new_user into User
	} or { 0 }

	// Generate and insert the token using user ID
	token := app.auth.add_token(user_id) or { '' }
	// Authenticate the user by adding the token to the cookies
	ctx.set_cookie(name: 'token', value: token)

	return ctx.redirect('/')
}

@[post]
pub fn (mut app App) login_post(mut ctx Context, name string, password string) veb.Result {
	user := app.find_user_by_name(name) or {
		ctx.error('Bad credentials')
		return ctx.redirect('/login')
	}
	// Verify user password using veb.auth
	if !auth.compare_password_with_hash(password, user.salt, user.password_hash) {
		ctx.error('Bad credentials')
		return ctx.redirect('/login')
	}
	// Find the user token in the Token table
	token := app.auth.add_token(user.id) or { '' }
	// Authenticate the user by adding the token to the cookies
	ctx.set_cookie(name: 'token', value: token)
	return ctx.redirect('/')
}

pub fn (mut app App) find_user_by_name(name string) ?User {
	// ... db query
	return User{}
}
```

On macOS, Postgres.app rejects passwordless `trust` connections from unknown
processes. Use a real password in the example above instead of `password: ''`.

## Security considerations

`hash_password_with_salt` and its related functions use `sha256` for hashing with a single
iteration. This is not secure for production use, and you should use a more secure hashing
algorithm and multiple iterations.

See also:
- [OWASP Password Storage Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html)

# Server Sent Events

This module implements the server side of `Server Sent Events`, SSE.
See [mozilla SSE][mozilla_sse]
as well as [whatwg][whatwg html spec]
for detailed description of the protocol, and a simple web browser client example.

## Usage

With SSE we want to keep the connection open, so we are able to
keep sending events to the client. But if we hold the connection open indefinitely
veb isn't able to process any other requests.

We can let veb know that it can continue processing other requests and that we will
handle the connection ourself by calling `ctx.takeover_conn()` and returning an empty result
with `veb.no_result()`. veb will not close the connection and we can handle
the connection in a separate thread.

**Example:**

```v ignore
import veb.sse

// endpoint handler for SSE connections
fn (app &App) sse(mut ctx Context) veb.Result {
	// let veb know that the connection should not be closed
	ctx.takeover_conn()
	// handle the connection in a new thread
	spawn handle_sse_conn(mut ctx)
	// we will send a custom response ourself, so we can safely return an empty result
	return veb.no_result()
}

fn handle_sse_conn(mut ctx Context) {
	// pass veb.Context
	mut sse_conn := sse.start_connection(mut ctx.Context)

	// send a message every second 3 times
	for _ in 0.. 3 {
		time.sleep(time.second)
		sse_conn.send_message(data: 'ping') or { break }
	}
	// close the SSE connection
	sse_conn.close()
}
```

Javascript code:

```js
const eventSource = new EventSource('/sse');

eventSource.addEventListener('message', (event) => {
	console.log('received message:', event.data);
});

eventSource.addEventListener('close', () => {
	console.log('closing the connection');
	// prevent browser from reconnecting
	eventSource.close();
});
```

[mozilla_sse]: https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events
[whatwg html spec]: https://html.spec.whatwg.org/multipage/server-sent-events.html#server-sent-events

import context
import time
import x.async as xasync

fn main() {
	mut group := xasync.new_group(context.background())

	group.go(fn (mut ctx context.Context) ! {
		_ = ctx
		time.sleep(20 * time.millisecond)
		return error('stop group')
	})!

	group.go(fn (mut ctx context.Context) ! {
		done := ctx.done()
		select {
			_ := <-done {
				return ctx.err()
			}
			1 * time.second {
				return error('worker did not observe cancellation')
			}
		}
	})!

	group.wait() or {
		println('group failed: ${err.msg()}')
		return
	}
}

import context
import x.async as xasync

fn main() {
	mut task := xasync.run[int](fn (mut ctx context.Context) !int {
		_ = ctx
		return 42
	})!

	value := task.wait()!
	println('task result: ${value}')
}

import context
import time
import x.async as xasync

fn main() {
	mut pool := xasync.new_pool(workers: 1, queue_size: 1)!
	started := chan bool{cap: 2}
	release := chan bool{cap: 2}
	accepted := chan bool{cap: 1}
	ran := chan bool{cap: 1}
	context_ran := chan bool{cap: 1}
	blocking_job := fn [started, release] (mut ctx context.Context) ! {
		_ = ctx
		started <- true
		_ := <-release
	}

	pool.try_submit(blocking_job)!
	if !wait_bool(started) {
		eprintln('first pool job did not start')
		exit(1)
	}
	pool.try_submit(blocking_job)!

	submitter := spawn fn [mut pool, accepted, ran] () {
		pool.submit_with_timeout(1 * time.second, fn [ran] (mut ctx context.Context) ! {
			_ = ctx
			ran <- true
		}) or {
			eprintln('bounded submit failed: ${err.msg()}')
			accepted <- false
			return
		}
		accepted <- true
	}()

	release <- true
	if !wait_bool(accepted) {
		eprintln('bounded submit was not accepted after capacity opened')
		exit(1)
	}

	release <- true
	if !wait_bool(ran) {
		eprintln('bounded submit job did not run')
		exit(1)
	}

	parent_ctx, cancel := xasync.with_cancel()
	defer {
		cancel()
	}
	pool.submit_with_context(parent_ctx, fn [context_ran] (mut ctx context.Context) ! {
		_ = ctx
		context_ran <- true
	})!
	if !wait_bool(context_ran) {
		eprintln('context-bounded submit job did not run')
		exit(1)
	}

	pool.close()!
	submitter.wait()
	println('timeout and context bounded submits completed')
}

fn wait_bool(ch chan bool) bool {
	select {
		ok := <-ch {
			return ok
		}
		1 * time.second {
			return false
		}
	}
	return false
}

import context
import mcp
import x.async as xasync

struct EchoArgs {
pub:
	text string
