			run_result <- err.msg()
			return
		}
		run_result <- 'ok'
	}()

	did_run := <-ran
	if !did_run {
		eprintln('owner stop job did not run')
		exit(1)
	}
	msg := <-run_result
	if msg != 'ok' {
		eprintln('run returned error: ${msg}')
